import {cellsOf} from './treasure-solver-model.mjs?v=dp1';
const controls=[...document.querySelectorAll('.hunt-layout button,.hunt-layout select')];controls.forEach(b=>b.disabled=true);
function feedback(message,retry){const box=document.getElementById('hunt-feedback');box.replaceChildren();box.hidden=!message;if(!message)return;const text=document.createElement('span');text.textContent=message;box.append(text);const button=document.createElement('button');button.textContent='Try again';button.onclick=retry;box.append(button);}
let data;try{const response=await fetch(new URL('./treasure-data/stages.json',import.meta.url));if(!response.ok)throw Error('Catalog unavailable');data=await response.json();controls.forEach(b=>b.disabled=false);}catch{feedback('Treasure Hunt could not load. Check your connection and try again.',()=>location.reload());}
if(data){
const $=s=>document.querySelector(s),key='milkroad-treasure-solver-v1';let state={stage:1,set:0,empty:[],found:[]},history=[],worker,selected=0,draft;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&data.stages[saved.stage-1]?.sets[saved.set]&&Array.isArray(saved.empty)&&Array.isArray(saved.found))state=saved;}catch{}
const stage=()=>data.stages[state.stage-1],set=()=>stage().sets[state.set];
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{}}
function action(fn){history.push(structuredClone(state));fn();save();render();}
function render(){feedback('',render);$('#board').setAttribute('aria-busy','true');worker?.terminate();const n=stage().rows;$('#stage-number').value=state.stage;renderTray();$('#undo').disabled=!history.length;$('#previous').disabled=state.stage===1;$('#next').disabled=state.stage===data.stages.length;
 if(!Array.isArray(state.tileStyles)||state.tileStyles.length!==n*n){state.tileStyles=Array.from({length:n*n},()=>1+Math.floor(Math.random()*4));save();}const board=$('#board');board.style.setProperty('--n',n);const size=n*11;board.style.cssText+=`width:calc(${size}% - 5px);height:calc(${size}% - 10px);left:${(100-size)/2}%;top:${(100-size)/2}%;`;board.replaceChildren();const covered=new Set(state.found.flatMap(p=>cellsOf(p,n)));for(let i=0;i<n*n;i++){const b=document.createElement('button');b.className='tile'+(state.empty.includes(i)||state.found.some(p=>p.revealed===i)?' empty':'');b.type='button';b.dataset.cell=i;b.style.setProperty("--tile-art",['url("treasure-data/tile-1.png")','url("treasure-data/tile-2.png")','url("treasure-data/tile-3.png")','url("treasure-data/tile-4.png")'][state.tileStyles[i]-1]);b.setAttribute('aria-label',`Row ${Math.floor(i/n)+1}, column ${i%n+1}${covered.has(i)?', confirmed treasure':state.empty.includes(i)?', empty':''}`);if(covered.has(i))b.innerHTML='<img class="mark" src="treasure-data/check.png" alt="Confirmed treasure">';b.onclick=()=>openTile(i);board.append(b);}
 for(const p of state.found){const t=set().treasures.find(t=>t.id===p.id),box=document.createElement('div'),img=document.createElement('img');box.className='placed';box.style.cssText=`left:${p.x/n*100}%;top:${p.y/n*100}%;width:${p.w/n*100}%;height:${p.h/n*100}%;`;const reveal=p.revealed??p.y*n+p.x,rx=reveal%n-p.x,ry=Math.floor(reveal/n)-p.y;box.style.clipPath=`inset(${ry/p.h*100}% ${(p.w-rx-1)/p.w*100}% ${(p.h-ry-1)/p.h*100}% ${rx/p.w*100}%)`;img.src=t.image;img.alt='';const angle=p.angle??(p.w!==t.width?90:0);img.style.cssText=angle%180?`position:absolute;width:${p.h/p.w*100}%;height:${p.w/p.h*100}%;left:50%;top:50%;transform:translate(-50%,-50%) rotate(${angle}deg)`: `width:100%;height:100%;transform:rotate(${angle}deg)`;box.append(img);board.append(box);}
 $('#status').textContent='Calculating tile chances…';worker=new Worker(new URL('./treasure-solver-worker.mjs?v=dp1',import.meta.url),{type:'module'});worker.onmessage=({data:r})=>{$('#board').setAttribute('aria-busy','false');if(r.error){$('#status').textContent=r.error;feedback(r.error,render);return;}const available=r.probabilities.filter((_,i)=>!covered.has(i)&&!state.empty.includes(i)),max=Math.max(0,...available);r.probabilities.forEach((p,i)=>{const b=board.querySelector(`[data-cell="${i}"]`);if(covered.has(i)||state.empty.includes(i))return;b.setAttribute('aria-label',b.getAttribute('aria-label')+`, estimated chance ${Math.round(p*100)} percent`);if(max>0&&Math.round(max*100)===Math.round(p*100))b.insertAdjacentHTML('beforeend',`<span class="recommend"><img src="treasure-data/thumb.png" alt="Recommended"><strong>${Math.round(p*100)}%</strong></span>`);});$('#status').textContent=max===0?'All treasures have been located.':`${r.exact?'Exact chances':'Estimated chances'}: ${Math.round(r.effective).toLocaleString()} ${r.method==='dp'?'valid layouts (exact DP)':r.exact?'enumerated layouts':'effective sampled layouts'}${!r.exact&&r.effective<500?' - Low confidence: retry for more samples.':''}`;};worker.onerror=()=>{$('#board').setAttribute('aria-busy','false');feedback('Calculation could not finish. Try again.',render);};worker.postMessage({set:set(),n,empty:state.empty,found:state.found});}
function renderTray(){const tray=$('#treasure-tray');tray.replaceChildren();for(const t of set().treasures){const found=state.found.filter(p=>p.id===t.id).length;for(let i=0;i<t.count;i++){const img=document.createElement('img');img.src=t.image;img.alt=`${t.name}${i<found?', found':', not found'}`;img.className=i<found?'found':'';img.style.width=`${t.width*18}px`;img.style.height=`${t.height*18}px`;tray.append(img);}}$('#set-previous').disabled=stage().sets.length<2;$('#set-next').disabled=stage().sets.length<2;}
function openTile(i){selected=i;draft=null;$('#placement').hidden=true;$('#treasures').replaceChildren();$('#empty-emoji').src=`treasure-data/empty-${Math.random()<.5?1:2}.png`;$('#mark-empty').setAttribute('aria-pressed','false');for(const t of set().treasures){const b=document.createElement('button'),icon=document.createElement('img'),caption=document.createElement('span');b.className='treasure-choice';b.dataset.treasure=t.id;b.setAttribute('aria-pressed','false');icon.src=t.image;icon.alt='';icon.style.width=`${t.width*17}px`;icon.style.height=`${t.height*17}px`;caption.textContent=t.name;b.append(icon,caption);b.disabled=state.found.filter(p=>p.id===t.id).length>=t.count;b.onclick=()=>choose(t,0);$('#treasures').append(b);}$('#tile-dialog').showModal();}
function choose(t,angle){draft={t,angle};$('#placement').hidden=false;document.querySelectorAll('.treasure-choice').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.treasure)===t.id)));const rotated=angle%180!==0,w=rotated?t.height:t.width,h=rotated?t.width:t.height;$('#rotate').onclick=()=>choose(t,(angle+90)%360);$('#rotate').setAttribute('aria-label',`Rotate treasure clockwise, currently ${angle} degrees`);$('.parts-wrap').style.setProperty('--parts-half',`${w*19}px`);const parts=$('#parts');parts.style.gridTemplateColumns=`repeat(${w},var(--part-size))`;parts.replaceChildren();for(let dy=0;dy<h;dy++)for(let dx=0;dx<w;dx++){const b=document.createElement('button');b.setAttribute('aria-label',`Treasure part row ${dy+1}, column ${dx+1}`);const art=document.createElement('img');art.src=t.image;art.alt='';art.style.cssText=`position:absolute;width:${t.width*100}%;height:${t.height*100}%;left:${(w/2-dx)*100}%;top:${(h/2-dy)*100}%;transform:translate(-50%,-50%) rotate(${angle}deg)`;b.append(art);b.onclick=()=>{const n=stage().rows,p={id:t.id,x:selected%n-dx,y:Math.floor(selected/n)-dy,w,h,angle,revealed:selected};const cells=cellsOf(p,n),used=new Set([...state.empty,...state.found.flatMap(f=>cellsOf(f,n))]);if(p.x<0||p.y<0||p.x+w>n||p.y+h>n||cells.some(c=>used.has(c))){$('#placement-note').textContent='That placement overlaps an empty tile, another treasure, or the edge.';return;}action(()=>state.found.push(p));$('#tile-dialog').close();};parts.append(b);}$('#placement-note').textContent='Select the part you uncovered. The whole footprint will be confirmed.';}
$('#mark-empty').onclick=()=>{action(()=>{state.found=state.found.filter(p=>!cellsOf(p,stage().rows).includes(selected));if(!state.empty.includes(selected))state.empty.push(selected);});$('#tile-dialog').close();};$('#mark-unknown').onclick=()=>{action(()=>{state.empty=state.empty.filter(c=>c!==selected);state.found=state.found.filter(p=>!cellsOf(p,stage().rows).includes(selected));});$('#tile-dialog').close();};$('#close-dialog').onclick=()=>$('#tile-dialog').close();
function changeStage(value){action(()=>state={stage:Math.max(1,Math.min(data.stages.length,value)),set:0,empty:[],found:[]});}
$('#previous').onclick=()=>changeStage(state.stage-1);$('#next').onclick=()=>changeStage(state.stage+1);$('#stage-number').onchange=e=>changeStage(Number(e.target.value));function cycleSet(step){action(()=>{state.set=(state.set+step+stage().sets.length)%stage().sets.length;state.empty=[];state.found=[];state.tileStyles=null;});}$('#set-previous').onclick=()=>cycleSet(-1);$('#set-next').onclick=()=>cycleSet(1);$('#clear').onclick=()=>action(()=>{state.empty=[];state.found=[];state.tileStyles=null;});$('#undo').onclick=()=>{if(history.length){state=history.pop();save();render();}};render();

}
